class Node<T> { T value; Node<T> next; Node(T v, Node<T> n) { value=v; next=n; } }
AtomicReference<Node<Integer>> head = new AtomicReference<>(null);
void push(int v) { Node<Integer> stary, nowy; do { stary=head.get(); nowy=new Node<>(v,stary); } while (!head.compareAndSet(stary,nowy)); }
Optional<Integer> pop() {
    Node<Integer> stary;
    do { stary = head.get(); if (stary==null) return Optional.empty(); } while (!head.compareAndSet(stary, stary.next));
    return Optional.of(stary.value);
}
// 4 watki push (250 kazdy), potem 4 watki pop dopoki niepuste, zsumuj zdjete elementy = 1000

AtomicInteger balance = new AtomicInteger(1000);
boolean tryWithdraw(int amount) {
    int current, next;
    do { current = balance.get(); if (current < amount) return false; next = current - amount; } while (!balance.compareAndSet(current, next));
    return true;
}
// 5 watkow wplacajacych: addAndGet(100) x10; 5 watkow wyplacajacych: tryWithdraw(50) x10
