AtomicReference<Map<String,String>> config = new AtomicReference<>(Collections.unmodifiableMap(new HashMap<>()));
void addKey(String key, String value) {
    Map<String,String> stara, nowa;
    do {
        stara = config.get();
        Map<String,String> kopia = new HashMap<>(stara);
        kopia.put(key, value);
        nowa = Collections.unmodifiableMap(kopia);
    } while (!config.compareAndSet(stara, nowa));
}
// 5 watkow, kazdy dodaje jeden UNIKALNY klucz - zweryfikuj config.get().size() == 5

