AtomicInteger permitsUsed = new AtomicInteger(0);
int MAX_PERMITS = 5;
boolean tryAcquire() {
    int current, next;
    do { current = permitsUsed.get(); if (current >= MAX_PERMITS) return false; next = current+1; } while (!permitsUsed.compareAndSet(current, next));
    return true;
}
int[] zaakceptowane = {0};
Object lock = new Object();
