for (Thread th : t) th.start();
for (Thread th : t) th.join(5_000);
System.out.println(zaakceptowane[0] == 5);

class Node<T> { T value; AtomicReference<Node<T>> next = new AtomicReference<>(); Node(T v) { value=v; } }
