    if (initialized.compareAndSet(false, true)) zwyciezca[0] = idx;
    for (int j=0;j<1000;j++) counter.incrementAndGet();
    for (int j=0;j<10;j++) push(stackHead, j); // push jak w Zadaniu 21
}); }
for (Thread th : t) th.start();
